/**
 * Tactical
 * Stabilization Resolver
 *
 * Resolves the effects of a successful or failed
 * Medicine stabilization attempt.
 *
 * The actual Medicine dice pool and TN are handled
 * elsewhere so those rules can remain configurable.
 */

/**
 * Resolve stabilization from Medicine successes.
 *
 * Rule:
 * - 0 successes: target is not stabilized.
 * - First success: stabilizes the target.
 * - Each additional success removes 1 Wound.
 *
 * @param {object} options
 * @param {number} options.successes
 * Number of successes generated by the Medicine roll.
 *
 * @param {number} options.currentWounds
 * Target's current Wounds Taken.
 *
 * @param {number} options.maxWounds
 * Target's maximum Wounds.
 *
 * @returns {object}
 */
export function resolveTacticalStabilization({
  successes = 0,
  currentWounds = 0,
  maxWounds = 0
} = {}) {

  const totalSuccesses = Math.max(
    0,
    Number(successes) || 0
  );

  const woundsBefore = Math.max(
    0,
    Number(currentWounds) || 0
  );

  const woundMaximum = Math.max(
    0,
    Number(maxWounds) || 0
  );

  /* -------------------------------------------- */
  /*  Stabilization                               */
  /* -------------------------------------------- */

  const stabilized =
    totalSuccesses >= 1;

  /* -------------------------------------------- */
  /*  Wound Removal                               */
  /* -------------------------------------------- */

  const extraSuccesses = Math.max(
    0,
    totalSuccesses - 1
  );

  const woundsRemoved = stabilized
    ? Math.min(
        woundsBefore,
        extraSuccesses
      )
    : 0;

  const woundsAfter = Math.max(
    0,
    woundsBefore - woundsRemoved
  );

  /* -------------------------------------------- */
  /*  Result                                      */
  /* -------------------------------------------- */

  return {
    successes: totalSuccesses,

    stabilized,

    wounds: {
      before: woundsBefore,
      removed: woundsRemoved,
      after: woundsAfter,
      max: woundMaximum
    }
  };
}
